}

func TestSearchInvalidJSON(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte("not-json"))
	}))
	defer server.Close()

	client := NewClient(Options{APIKey: "test-key", BaseURL: server.URL})
	_, err := client.Search(context.Background(), SearchRequest{Query: "coffee"})
	if err == nil {
		t.Fatal("expected error")
	}
}

func TestBuildSearchBodyOmitsEmptyPriceLevels(t *testing.T) {
	request := SearchRequest{Query: "coffee", Filters: &Filters{PriceLevels: []int{9}}}
	body := buildSearchBody(request)
	payload, err := json.Marshal(body)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	if bytes.Contains(payload, []byte("priceLevels")) {
		t.Fatalf("unexpected priceLevels in payload")
	}

	request = SearchRequest{Query: "coffee", Filters: &Filters{PriceLevels: []int{0, 2}}}
	body = buildSearchBody(request)
	levels, ok := body["priceLevels"].([]string)
	if !ok || len(levels) != 2 || levels[0] != "PRICE_LEVEL_FREE" || levels[1] != "PRICE_LEVEL_MODERATE" {
		t.Fatalf("unexpected price levels: %#v", body["priceLevels"])
	}
}

func TestSearchAllowsFreePriceLevelFilter(t *testing.T) {
	err := validateSearchRequest(SearchRequest{
		Query:   "coffee",
		Limit:   1,
		Filters: &Filters{PriceLevels: []int{0}},
	})
	if err != nil {
		t.Fatalf("expected free price level to be valid, got %v", err)
	}
}

func TestSearchRejectsInvalidPriceLevelFilter(t *testing.T) {
	err := validateSearchRequest(SearchRequest{
		Query:   "coffee",
		Limit:   1,
		Filters: &Filters{PriceLevels: []int{-1}},
	})
	var validationErr ValidationError
	if !errors.As(err, &validationErr) {
		t.Fatalf("expected validation error, got %v", err)
	}
	if validationErr.Field != "filters.price_levels" {
		t.Fatalf("unexpected field: %s", validationErr.Field)
	}
}

package places

import (
	"errors"
	"fmt"
	"math"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"
)

func TestRequestsRejectNonFiniteNumbersBeforeHTTP(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		calls.Add(1)
		_, _ = fmt.Fprint(w, `{"routes":[{"polyline":{"encodedPolyline":"??"}}],"places":[]}`)
	}))
	defer server.Close()
	client := NewClient(Options{APIKey: "[REDACTED]", BaseURL: server.URL, RoutesBaseURL: server.URL, DirectionsBaseURL: server.URL})
	ctx := t.Context()
	cases := []struct {
		name, field string
		run         func(float64) error
	}{
		{"search latitude", "location_bias.lat", func(v float64) error {
			_, err := client.Search(ctx, SearchRequest{Query: "coffee", LocationBias: &LocationBias{Lat: v, RadiusM: 1}})
			return err
		}},
		{"search longitude", "location_bias.lng", func(v float64) error {
			_, err := client.Search(ctx, SearchRequest{Query: "coffee", LocationBias: &LocationBias{Lng: v, RadiusM: 1}})
			return err
		}},
		{"search rating", "filters.min_rating", func(v float64) error {
			_, err := client.Search(ctx, SearchRequest{Query: "coffee", Filters: &Filters{MinRating: &v}})
			return err
		}},
		{"autocomplete radius", "location_bias.radius_m", func(v float64) error {
			_, err := client.Autocomplete(ctx, AutocompleteRequest{Input: "cof", LocationBias: &LocationBias{RadiusM: v}})
			return err
		}},
		{"nearby latitude", "location_restriction.lat", func(v float64) error {
			_, err := client.NearbySearch(ctx, NearbySearchRequest{LocationRestriction: &LocationBias{Lat: v, RadiusM: 1}})
			return err
		}},
		{"nearby radius", "location_restriction.radius_m", func(v float64) error {
			_, err := client.NearbySearch(ctx, NearbySearchRequest{LocationRestriction: &LocationBias{RadiusM: v}})
			return err
		}},
		{"directions origin", "from.lat", func(v float64) error {
			_, err := client.Directions(ctx, DirectionsRequest{FromLocation: &LatLng{Lat: v}, To: "B"})
			return err
		}},
		{"directions destination", "to.lng", func(v float64) error {
			_, err := client.Directions(ctx, DirectionsRequest{From: "A", ToLocation: &LatLng{Lng: v}})
			return err
		}},
		{"route radius", "radius_m", func(v float64) error {
			_, err := client.Route(ctx, RouteRequest{Query: "coffee", From: "A", To: "B", RadiusM: v})
			return err
		}},
	}
	for _, tt := range cases {
		t.Run(tt.name, func(t *testing.T) {
			for _, value := range []float64{math.NaN(), math.Inf(1), math.Inf(-1)} {
				before := calls.Load()
				err := tt.run(value)
				var validation ValidationError
				if !errors.As(err, &validation) || validation.Field != tt.field {
					t.Errorf("value %v: want validation field %s, got %v", value, tt.field, err)
				}
				if calls.Load() != before {
					t.Errorf("value %v reached HTTP", value)
				}
			}
		})
	}
}

import assert from "node:assert/strict";
import test from "node:test";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";

import { metadataText } from "./llms-metadata.mjs";

test("rejects markup instead of trying to sanitize it", () => {
  assert.throws(
    () => metadataText("<scrip<script>t>alert(1)</script>", "title"),
    /title must be plain text/,
  );
});

test("decodes supported entities exactly once", () => {
  assert.equal(metadataText("&amp;quot; &quot; &mdash;", "title"), '&quot; " -');
});

test("the generated index preserves descriptions in valid HTML attributes", (t) => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "goplaces-llms-metadata-"));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  fs.mkdirSync(path.join(root, "scripts"));
  fs.mkdirSync(path.join(root, "docs"));
  for (const script of ["generate-llms.mjs", "llms-metadata.mjs"]) {
    fs.copyFileSync(new URL(script, import.meta.url), path.join(root, "scripts", script));
  }
  fs.writeFileSync(path.join(root, "docs", "CNAME"), "docs.example.test\n");
  const cases = [
    ['<meta name="description" content="A place\'s full details">', "A place's full details"],
    ["<meta name='description' content='Search for a \"coffee shop\" nearby'>", 'Search for a "coffee shop" nearby'],
    ['<meta content="Reordered description" name="description">', "Reordered description"],
    ['<META data-name="ignored" content="Case and spacing" NAME = "DESCRIPTION">', "Case and spacing"],
    ['<meta name=description content="Unquoted name">', "Unquoted name"],
    ['<meta name="other" content="Ignore this"><meta name="description" content="Select description">', "Select description"],
    ['<meta name="description" content="Decode &amp;quot; &quot; once">', 'Decode &quot; " once'],
  ];
  for (const [meta, expected] of cases) {
    fs.writeFileSync(path.join(root, "docs", "index.html"), `<title>Fixture</title>${meta}`);
    const result = spawnSync(process.execPath, [path.join(root, "scripts", "generate-llms.mjs")], { encoding: "utf8" });
    assert.equal(result.status, 0, result.stderr);
    const index = fs.readFileSync(path.join(root, "docs", "llms.txt"), "utf8");
    assert.ok(index.includes(`- Fixture: https://docs.example.test/ - ${expected}\n`), index);
  }
  fs.writeFileSync(path.join(root, "docs", "llms.txt"), "last valid index\n");
  fs.writeFileSync(path.join(root, "docs", "index.html"), '<title>Fixture</title><meta content="<script>bad</script>" name="description">');
  const rejected = spawnSync(process.execPath, [path.join(root, "scripts", "generate-llms.mjs")], { encoding: "utf8" });
  assert.notEqual(rejected.status, 0);
  assert.match(rejected.stderr, /description must be plain text/);
  assert.equal(fs.readFileSync(path.join(root, "docs", "llms.txt"), "utf8"), "last valid index\n");
});

name: ClawSweeper Dispatch

on:
  issues:
    types: [opened, reopened, edited, labeled, unlabeled]
  issue_comment:
    types: [created, edited]
  pull_request_target: # zizmor: ignore[dangerous-triggers] maintainer-owned external dispatch; no checkout or untrusted PR code execution
    types: [opened, reopened, synchronize, ready_for_review, edited, labeled, unlabeled]

permissions:
  contents: read

concurrency:
  group: clawsweeper-dispatch-${{ github.repository }}-${{ github.event_name }}-${{ github.event.comment.id || github.event.issue.number || github.event.pull_request.number || github.run_id }}-${{ endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled') && github.actor || 'dispatchable' }}
  cancel-in-progress: ${{ github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review' }}

jobs:
  dispatch:
    runs-on: ubuntu-latest
    # id-token proves this repository, event, branch, and run to the queue.
    # The job never checks out or executes pull request code.
    permissions:
      contents: read
      id-token: write
    if: ${{ !(endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled')) }}
    env:
      SUPERSEDES_IN_PROGRESS: ${{ (github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review') && 'true' || 'false' }}
    steps:
      - name: Debounce bursty metadata events
        if: ${{ github.event.action == 'labeled' || github.event.action == 'unlabeled' }}
        run: sleep 20

      - name: Pre-filter ClawSweeper comment
        id: comment_filter
        if: ${{ github.event_name == 'issue_comment' }}
        env:
          COMMENT_BODY: ${{ github.event.comment.body }}
        run: |
          set -euo pipefail
          if [[ "$COMMENT_BODY" == *"<!-- clawsweeper-maintainer-opt-in:"* ]]; then
            echo "is_command=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          if grep -Eiq '(^|[[:space:]])@(clawsweeper|openclaw-clawsweeper)\b(\[bot\])?|(^|[[:space:]])/(clawsweeper|review|re-review|rerun([[:space:]]+|-)?review|status|explain|fix|build|implement|create([[:space:]]+|-)?pr|fix([[:space:]]+|-)?issue|autofix|auto([[:space:]]+|-)?fix|automerge|auto([[:space:]]+|-)?merge|approve|stop|autoclose)\b' <<< "$COMMENT_BODY"; then
            echo "is_command=true" >> "$GITHUB_OUTPUT"
          else
            echo "is_command=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Dispatch exact ClawSweeper review
        if: ${{ github.event_name != 'issue_comment' }}
        env:
          TARGET_REPO: ${{ github.repository }}
          TARGET_BRANCH: ${{ github.event.repository.default_branch }}
          ITEM_NUMBER: ${{ github.event.issue.number || github.event.pull_request.number }}
          ITEM_KIND: ${{ github.event_name == 'pull_request_target' && 'pull_request' || 'issue' }}
          SOURCE_EVENT: ${{ github.event_name }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          source_identity_json="$(node <<'NODE'
          const crypto = require("node:crypto");
          const fs = require("node:fs");
          const event = JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH, "utf8"));
          const pullRequest = event.pull_request && typeof event.pull_request === "object"
            ? event.pull_request
            : {};
          const issue = event.issue && typeof event.issue === "object" ? event.issue : {};
          const source = process.env.ITEM_KIND === "pull_request" ? pullRequest : issue;
          const headSha = String(pullRequest.head?.sha || "").trim().toLowerCase();
          const baseSha = String(pullRequest.base?.sha || "").trim().toLowerCase();
          const updatedAt = String(pullRequest.updated_at || "").trim();
          const queueClaim = {};
          const result = { queue_claim: queueClaim };
          const sourceUpdatedAt = String(source.updated_at || "").trim();
          if (sourceUpdatedAt && Number.isFinite(Date.parse(sourceUpdatedAt))) {
            queueClaim.source_updated_at = sourceUpdatedAt;
          }
          if (
            typeof source.title === "string" &&
            (source.body === null || typeof source.body === "string") &&
            typeof source.locked === "boolean" &&
            Array.isArray(source.labels)
          ) {
            const labels = [
              ...new Set(
                source.labels
                  .map((label) => String(label?.name || "").trim().toLowerCase())
                  .filter((label) => {
                    if (!label) return false;
                    if (label === "proof: override") return true;
                    if (/^(?:status|rating|proof|merge-risk|impact|issue-rating):/.test(label)) return false;
                    if (/^p[0-3]$/.test(label)) return false;
                    if ([
                      "maturity:stable",
                      "feature: ✨ showcase",
                      "good first issue",
                      "mantis: telegram-visible-proof",
                      "proof: telegram-e2e",
                      "triage: needs-real-behavior-proof",
                      "clawsweeper-recovery-stuck",
                      "no-stale",
                      "stale",
                    ].includes(label)) return false;
                    return !label.startsWith("clawsweeper:") || [
                      "clawsweeper:autofix",
                      "clawsweeper:automerge",
                      "clawsweeper:human-review",
                      "clawsweeper:manual-only",
                      "clawsweeper:bulk-filed",
                    ].includes(label);
                  }),
              ),
            ].sort();
            queueClaim.source_content_revision = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 2,
                  title: source.title,
                  body: source.body || "",
                  locked: source.locked,
                  close_guard_labels: labels,
                }),
              )
              .digest("hex");
          }
          if (process.env.ITEM_KIND === "pull_request") {
            if (/^[0-9a-f]{40}$/.test(headSha)) queueClaim.source_head_sha = headSha;
            if (/^[0-9a-f]{40}$/.test(baseSha)) queueClaim.source_base_sha = baseSha;
            if (typeof pullRequest.draft === "boolean") {
              queueClaim.source_is_draft = pullRequest.draft;
            }
          }
          if (
            process.env.ITEM_KIND !== "pull_request" ||
            !/^[0-9a-f]{40}$/.test(headSha) ||
            !updatedAt
          ) {
            process.stdout.write(JSON.stringify(result));
          } else {
            result.ingress_route = "target_dispatcher";
            result.ingress_fingerprint = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 1,
                  target_repo: String(process.env.TARGET_REPO || "").toLowerCase(),
                  item_number: Number(process.env.ITEM_NUMBER),
                  action: String(process.env.SOURCE_ACTION || ""),
                  head_sha: headSha,
                  updated_at: updatedAt,
                  body: typeof pullRequest.body === "string" ? pullRequest.body : "",
                  label: String(event.label?.name || ""),
                }),
              )
              .digest("hex");
            process.stdout.write(JSON.stringify(result));
          }
          NODE
          )"
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --arg target_branch "$TARGET_BRANCH" \
            --argjson item_number "$ITEM_NUMBER" \
            --arg item_kind "$ITEM_KIND" \
            --arg source_event "$SOURCE_EVENT" \
            --arg source_action "$SOURCE_ACTION" \
            --argjson source_identity "$source_identity_json" \
            --argjson supersedes_in_progress "$SUPERSEDES_IN_PROGRESS" \
            '{target_repo:$target_repo,target_branch:$target_branch,item_number:$item_number,item_kind:$item_kind,source_event:$source_event,source_action:$source_action,supersedes_in_progress:$supersedes_in_progress} + $source_identity')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1
      - name: Dispatch ClawSweeper comment
        if: >-
          ${{
            github.event_name == 'issue_comment' &&
            steps.comment_filter.outputs.is_command == 'true'
          }}
        env:
          TARGET_REPO: ${{ github.repository }}
          ITEM_NUMBER: ${{ github.event.issue.number }}
          COMMENT_ID: ${{ github.event.comment.id }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --argjson item_number "$ITEM_NUMBER" \
            --argjson comment_id "$COMMENT_ID" \
            --arg source_action "$SOURCE_ACTION" \
            '{target_repo:$target_repo,item_number:$item_number,comment_id:$comment_id,source_event:"issue_comment",source_action:$source_action}')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1

// Package goplaces provides a Go client for the Google Places API (New).
package goplaces

import (
	"context"

	"github.com/steipete/goplaces/internal/places"
)

// DefaultBaseURL is the default endpoint for the Places API (New).
const DefaultBaseURL = places.DefaultBaseURL

// ErrMissingAPIKey indicates a missing API key.
var ErrMissingAPIKey = [REDACTED]

// NewClient builds a client with sane defaults.
func NewClient(opts Options) *Client {
	return &Client{inner: *places.NewClient(opts)}
}

// Client wraps access to the Google Places API.
type Client struct {
	inner places.Client
}

// Search runs a Places text search.
func (c *Client) Search(ctx context.Context, req SearchRequest) (SearchResponse, error) {
	return c.inner.Search(ctx, req)
}

// Autocomplete returns place and query suggestions for partial input.
func (c *Client) Autocomplete(ctx context.Context, req AutocompleteRequest) (AutocompleteResponse, error) {
	return c.inner.Autocomplete(ctx, req)
}

// NearbySearch searches places near a lat/lng radius.
func (c *Client) NearbySearch(ctx context.Context, req NearbySearchRequest) (NearbySearchResponse, error) {
	return c.inner.NearbySearch(ctx, req)
}

// Details fetches place details by place ID.
func (c *Client) Details(ctx context.Context, placeID string) (PlaceDetails, error) {
	return c.inner.Details(ctx, placeID)
}

// DetailsWithOptions fetches place details with optional locale and field options.
func (c *Client) DetailsWithOptions(ctx context.Context, req DetailsRequest) (PlaceDetails, error) {
	return c.inner.DetailsWithOptions(ctx, req)
}

// PhotoMedia fetches a photo media URL.
func (c *Client) PhotoMedia(ctx context.Context, req PhotoMediaRequest) (PhotoMediaResponse, error) {
	return c.inner.PhotoMedia(ctx, req)
}

// Resolve resolves a free-form location into place candidates.
func (c *Client) Resolve(ctx context.Context, req LocationResolveRequest) (LocationResolveResponse, error) {
	return c.inner.Resolve(ctx, req)
}

// Route searches for places along a route between two locations.
func (c *Client) Route(ctx context.Context, req RouteRequest) (RouteResponse, error) {
	return c.inner.Route(ctx, req)
}

// Directions fetches directions between two locations.
func (c *Client) Directions(ctx context.Context, req DirectionsRequest) (DirectionsResponse, error) {
	return c.inner.Directions(ctx, req)
}

type (
	// Options configures the Places client.
	Options = places.Options
	// ValidationError describes an invalid request payload.
	ValidationError = places.ValidationError
	// APIError represents an HTTP error from the Places API.
	APIError = places.APIError

	// SearchRequest defines a text search with optional filters.
	SearchRequest = places.SearchRequest
	// Filters are optional search refinements.
	Filters = places.Filters
	// LocationBias limits search results to a circular area.
	LocationBias = places.LocationBias
	// LatLng holds geographic coordinates.
	LatLng = places.LatLng
	// SearchResponse contains a list of places and optional pagination token.
	SearchResponse = places.SearchResponse

	// AutocompleteRequest defines input for autocomplete suggestions.
	AutocompleteRequest = places.AutocompleteRequest
	// AutocompleteResponse contains suggestions from autocomplete.
	AutocompleteResponse = places.AutocompleteResponse
	// AutocompleteSuggestion is a place or query prediction.
	AutocompleteSuggestion = places.AutocompleteSuggestion

	// NearbySearchRequest defines a nearby search query.
	NearbySearchRequest = places.NearbySearchRequest
	// NearbySearchResponse contains nearby search results.
	NearbySearchResponse = places.NearbySearchResponse
	// PlaceSummary is a compact view of a place.
	PlaceSummary = places.PlaceSummary
	// PlaceDetails is a detailed view of a place.
	PlaceDetails = places.PlaceDetails
	// DetailsRequest fetches place details with optional locale hints.
	DetailsRequest = places.DetailsRequest

	// Review represents a user review of a place.
	Review = places.Review
	// LocalizedText is a text value with an optional language code.
	LocalizedText = places.LocalizedText
	// AuthorAttribution describes a review author.
	AuthorAttribution = places.AuthorAttribution
	// ReviewVisitDate describes the date a reviewer visited a place.
	ReviewVisitDate = places.ReviewVisitDate
	// Photo describes photo metadata for a place.
	Photo = places.Photo
	// PhotoMediaRequest fetches a photo URL from a photo resource name.
	PhotoMediaRequest = places.PhotoMediaRequest
	// PhotoMediaResponse contains the photo URL for a photo name.
	PhotoMediaResponse = places.PhotoMediaResponse

	// LocationResolveRequest resolves a text location into place candidates.
	LocationResolveRequest = places.LocationResolveRequest
	// LocationResolveResponse contains resolved locations.
	LocationResolveResponse = places.LocationResolveResponse
	// ResolvedLocation is a place candidate for a location string.
	ResolvedLocation = places.ResolvedLocation

	// RouteRequest describes a query to search along a route.
	RouteRequest = places.RouteRequest
	// RouteResponse contains sampled waypoints with search results.
	RouteResponse = places.RouteResponse
	// RouteWaypoint ties a sampled route location to search results.
	RouteWaypoint = places.RouteWaypoint

	// DirectionsRequest describes a directions query between two locations.
	DirectionsRequest = places.DirectionsRequest
	// DirectionsResponse contains a single route summary and steps.
	DirectionsResponse = places.DirectionsResponse
	// DirectionsStep is a single navigation step.
	DirectionsStep = places.DirectionsStep
)
